trusted_authors:
- engineer_a
- engineer_b
always_two:
- payments/
- .github/workflows/
- .mergeguard/
- .codex/
- .claude/
always_one: []
zero_review_allowed: true
zero_review_additive: true
prompter_counts_as_reviewer: false
api_break_tier: 2
breaker:
  window_days: 7
  strikes_to_trip: 2
  cooldown_days: 14
----
[tool.pytest.ini_options]
testpaths = ["tests"]
pythonpath = ["."]
----
{
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "/Users/QTG2659/codex-project/mergeguard/.venv/bin/python -m mergeguard.hooks session-start",
            "timeout": 20
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "/Users/QTG2659/codex-project/mergeguard/.venv/bin/python -m mergeguard.hooks post-tool-use",
            "timeout": 20
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "/Users/QTG2659/codex-project/mergeguard/.venv/bin/python -m mergeguard.hooks stop",
            "timeout": 20
          }
        ]
      }
    ]
  }
}

